    "code": "#include <Servo.h>\n\nServo myservo;  // Create servo object to control a 360-degree servo\nint potpin = A0;  // Analog pin connected to the potentiometer\nint val;    // Variable to read the value from the analog pin\n\nvoid setup() {\n  myservo.attach(9);  // Attaches the servo on pin 9 to the servo object\n}\n\nvoid loop() {\n  val = analogRead(potpin);            // Reads the potentiometer value (0 to 1023)\n  val = map(val, 0, 1023, 0, 180);     // Scales it to use with the servo (0 to 180)\n  myservo.write(val);                  // Sets the servo speed and direction\n  delay(15);                           // Waits for the servo to get there\n}\n"
