    "files": {
      "sketch.ino": "#include <Wire.h>\n#include <LiquidCrystal_I2C.h>\n#include <DHT.h>\n\n#define DHTPIN 2     // Digital pin connected to the DHT11 data pin\n#define DHTTYPE DHT11   // Defining sensor type as DHT11\n\nDHT dht(DHTPIN, DHTTYPE);\nLiquidCrystal_I2C lcd(0x27, 16, 2); // Set the LCD address to 0x27 for a 16 chars and 2 line display\n\nvoid setup() {\n  Serial.begin(115200);\n  dht.begin();\n  lcd.init();          // Initialize the LCD\n  lcd.backlight();     // Turn on the backlight\n}\n\nvoid loop() {\n  // Wait 2 seconds between measurements (DHT11 is slow)\n  delay(2000);\n  lcd.clear();\n\n  // Read humidity and temperature\n  float h = dht.readHumidity();\n  float t = dht.readTemperature(); // Read temperature in Celsius\n\n  // Check if readings failed and exit early to try again\n  if (isnan(h) || isnan(t)) {\n    lcd.setCursor(0, 0);\n    lcd.print(\"Sensor Error\");\n    return;\n  }\n\n  // Display Temperature on LCD\n  lcd.setCursor(0, 0);\n  lcd.print(\"Temp: \");\n  lcd.print(t);\n  lcd.print(\" °C\");\n\n  // Display Humidity on LCD\n  lcd.setCursor(0, 1);\n  lcd.print(\"Humidity: \");\n  lcd.print(h);\n  lcd.print(\" %\");\n}\n"
    }
