    "files": {
      "sketch.ino": "/*\n * DS3231 RTC Clock + LCD + Hourly NTP Sync (non-blocking)\n *\n * Uses ntpEpoch() to fetch real UTC time from the browser.\n * Syncs the DS3231 RTC every hour using millis() timers.\n * Displays time and temperature on Serial + 16x2 I2C LCD.\n *\n * Wiring:\n *   DS3231 & LCD share I2C bus: SDA->D21, SCL->D22\n *   Both powered from 3V3\n */\n\n#include <Wire.h>\n#include <RtcDS3231.h>\n#include <LiquidCrystal_I2C.h>\n#include <WiFi.h>\n\n// IST = UTC + 5:30 = 19800 seconds\n// Change this for your timezone\nvar gmtOffsetSec = 19800;\n\n// Non-blocking intervals\nvar DISPLAY_INTERVAL = 1000;\n// var NTP_SYNC_INTERVAL = 3600000;\nvar NTP_SYNC_INTERVAL = 30000;//sync every 30 seconds for demonstration\n\nvar lastDisplayTime = 0;\nvar lastNtpSyncTime = 0;\n\nRtcDS3231<TwoWire> Rtc(Wire);\nLiquidCrystal_I2C lcd(0x27, 16, 2);\n\n// Helper: sync RTC from NTP with full date\nvoid syncRtcFromNtp() {\n  var epoch = ntpEpoch() + gmtOffsetSec;\n  var h = ((epoch % 86400) / 3600) | 0;\n  var m = ((epoch % 3600) / 60) | 0;\n  var s = (epoch % 60) | 0;\n\n  // Compute date from epoch\n  var days = (epoch / 86400) | 0;\n  var yr = 1970;\n  while (days >= 365) {\n    var leap = ((yr % 4 == 0 && yr % 100 != 0) || (yr % 400 == 0)) ? 1 : 0;\n    if (days < 365 + leap) break;\n    days -= (365 + leap);\n    yr++;\n  }\n  var monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n  if ((yr % 4 == 0 && yr % 100 != 0) || (yr % 400 == 0)) monthDays[1] = 29;\n  var mo = 0;\n  var dy = days;\n  while (mo < 12 && dy >= monthDays[mo]) {\n    dy -= monthDays[mo];\n    mo++;\n  }\n  mo++;\n  dy++;\n\n  Rtc.SetDateTime(RtcDateTime(yr, mo, dy, h, m, s));\n  Serial.print(\"[NTP] Synced: \");\n  if (h < 10) Serial.print(\"0\");\n  Serial.print(h);\n  Serial.print(\":\");\n  if (m < 10) Serial.print(\"0\");\n  Serial.print(m);\n  Serial.print(\":\");\n  if (s < 10) Serial.print(\"0\");\n  Serial.println(s);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  lcd.init();\n  lcd.backlight();\n\n  // Connect WiFi (simulated)\n  WiFi.begin(\"ArduSimNet\", \"simulator\");\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(300);\n  }\n  Serial.println(\"WiFi connected\");\n\n  // Initialize RTC\n  Rtc.Begin();\n  if (!Rtc.IsDateTimeValid()) {\n    Serial.println(\"RTC lost power - setting from NTP\");\n  }\n  if (!Rtc.IsRunning()) {\n    Rtc.SetIsRunning(true);\n  }\n\n  // Sync immediately on boot\n  syncRtcFromNtp();\n\n  lastNtpSyncTime = millis();\n  lastDisplayTime = millis();\n\n  lcd.clear();\n  lcd.setCursor(0, 0);\n  lcd.print(\"DS3231 + NTP\");\n  lcd.setCursor(0, 1);\n  lcd.print(\"Syncing...\");\n  delay(1500);\n  lcd.clear();\n}\n\nvoid loop() {\n  var now = millis();\n\n  // Non-blocking NTP sync every 1 hour\n  if (now - lastNtpSyncTime >= NTP_SYNC_INTERVAL || lastNtpSyncTime == 0) {\n    lastNtpSyncTime = now;\n    syncRtcFromNtp();\n  }\n\n  // Non-blocking 1-second display refresh\n  if (now - lastDisplayTime >= DISPLAY_INTERVAL) {\n    lastDisplayTime = now;\n    RtcDateTime dt = Rtc.GetDateTime();\n    RtcTemperature temp = Rtc.GetTemperature();\n\n    // Serial output\n    if (dt.Hour() < 10) Serial.print(\"0\");\n    Serial.print(dt.Hour());\n    Serial.print(\":\");\n    if (dt.Minute() < 10) Serial.print(\"0\");\n    Serial.print(dt.Minute());\n    Serial.print(\":\");\n    if (dt.Second() < 10) Serial.print(\"0\");\n    Serial.print(dt.Second());\n    Serial.print(\"  \");\n    if (dt.Day() < 10) Serial.print(\"0\");\n    Serial.print(dt.Day());\n    Serial.print(\"/\");\n    if (dt.Month() < 10) Serial.print(\"0\");\n    Serial.print(dt.Month());\n    Serial.print(\"/\");\n    Serial.print(dt.Year());\n    Serial.print(\"  Temp: \");\n    Serial.print(temp.AsFloatDegC(), 1);\n    Serial.println(\" C\");\n\n    // LCD row 0: time\n    lcd.setCursor(0, 0);\n    if (dt.Hour() < 10) lcd.print(\"0\");\n    lcd.print(dt.Hour());\n    lcd.print(\":\");\n    if (dt.Minute() < 10) lcd.print(\"0\");\n    lcd.print(dt.Minute());\n    lcd.print(\":\");\n    if (dt.Second() < 10) lcd.print(\"0\");\n    lcd.print(dt.Second());\n    lcd.print(\"  \");\n    lcd.print(temp.AsFloatDegC(), 1);\n    lcd.print(\"°C\");\n\n    // LCD row 1: date\n    lcd.setCursor(0, 1);\n    if (dt.Day() < 10) lcd.print(\"0\");\n    lcd.print(dt.Day());\n    lcd.print(\"/\");\n    if (dt.Month() < 10) lcd.print(\"0\");\n    lcd.print(dt.Month());\n    lcd.print(\"/\");\n    lcd.print(dt.Year());\n  }\n}"
    }
