    "code": "/*\n* ESP-NOW Sender — Board 1\n* Sends a counter to Board 2 every second\n* Green LED on D2 blinks on each send\n*/\n\n#include <esp_now.h>\n#include <WiFi.h>\n\n// Receiver MAC address (Board 2)\nuint8_t receiverMAC[] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};\n\nesp_now_peer_info_t peerInfo;\n\n// Data structure to send\ntypedef struct {\n  int counter;\n  float temperature;\n} DataPacket;\n\nDataPacket myData;\nint sendCount = 0;\n\n// Callback when data is sent\nvoid OnDataSent(const uint8_t *mac, esp_now_send_status_t status) {\n  if (status == ESP_NOW_SEND_SUCCESS) {\n    Serial.println(\"Data sent OK!\");\n  } else {\n    Serial.println(\"Send failed!\");\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(2, OUTPUT);\n\n// Initialize WiFi in station mode\n  WiFi.mode(WIFI_STA);\n  Serial.print(\"Sender MAC: \");\n  Serial.println(WiFi.macAddress());\n\n// Initialize ESP-NOW\n  esp_now_init();\n  esp_now_register_send_cb(OnDataSent);\n\n// Configure peer\n  memcpy(peerInfo.peer_addr, receiverMAC, 6);\n  peerInfo.channel = 0;\n  peerInfo.encrypt = false;\n  esp_now_add_peer(&peerInfo);\n\n  Serial.println(\"ESP-NOW Sender ready!\");\n}\n\nvoid loop() {\n  sendCount++;\n  myData.counter = sendCount;\n  myData.temperature = 22.5 + (sendCount % 10) * 0.5;\n\n// Blink LED on send\n  digitalWrite(2, HIGH);\n\n// Send data\n  esp_now_send(receiverMAC, (uint8_t *)&myData, sizeof(myData));\n\n  Serial.print(\"Sent #\");\n  Serial.print(sendCount);\n  Serial.print(\" temp=\");\n  Serial.println(myData.temperature);\n\n  digitalWrite(2, LOW);\n  delay(1000);\n}\n\n/*\n#include <esp_now.h>\n#include <WiFi.h>\n\n// Data structure to receive\ntypedef struct {\nint counter;\nfloat temperature;\n} DataPacket;\n\nDataPacket incomingData;\n\n// Callback when data is received\nvoid OnDataRecv(const uint8_t *mac, const uint8_t *data, int len) {\nmemcpy(&incomingData, data, sizeof(incomingData));\n\nSerial.print(\"Received #\");\nSerial.print(incomingData.counter);\nSerial.print(\" temp=\");\nSerial.println(incomingData.temperature);\n\n// Blink LED on receive\ndigitalWrite(2, HIGH);\ndelay(50);\ndigitalWrite(2, LOW);\n}\n\nvoid setup() {\nSerial.begin(115200);\npinMode(2, OUTPUT);\n\n// Initialize WiFi in station mode\nWiFi.mode(WIFI_STA);\nSerial.print(\"Receiver MAC: \");\nSerial.println(WiFi.macAddress());\n\n// Initialize ESP-NOW\nesp_now_init();\nesp_now_register_recv_cb(OnDataRecv);\n\nSerial.println(\"ESP-NOW Receiver ready - waiting for data...\");\n}\n\nvoid loop() {\ndelay(100);\n}\n*/",
    "board2Code": "/*\n * ESP-NOW Receiver — Board 2\n * Receives data from Board 1 (Sender)\n * Blue LED on D2 blinks on each receive\n */\n#include <Wire.h>\n#include <esp_now.h>\n#include <WiFi.h>\n#include <Wire.h>\n#include <LiquidCrystal_I2C.h>\n\nLiquidCrystal_I2C lcd(0x27, 16, 2);\n\n\n// Data structure to receive\ntypedef struct {\n  int counter;\n  float temperature;\n} DataPacket;\n\nDataPacket incomingData;\n\n// Callback when data is received\nvoid OnDataRecv(const uint8_t *mac, const uint8_t *data, int len) {\n  memcpy(&incomingData, data, sizeof(incomingData));\n  \n  Serial.print(\"Received #\");\n  Serial.print(incomingData.counter);\n  Serial.print(\" temp=\");\n  Serial.println(incomingData.temperature);\nlcd.clear();\n    lcd.setCursor(0, 0);\n    lcd.print(\"RX data = \");\n    lcd.setCursor(0, 1);\n    lcd.print(incomingData.counter);\n  \n  // Blink LED on receive\n  digitalWrite(2, HIGH);\n  delay(50);\n  digitalWrite(2, LOW);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(2, OUTPUT);\n lcd.init();\n  lcd.backlight();\n  lcd.setCursor(0, 0);\n  lcd.clear();\n  \n  // Initialize WiFi in station mode\n  WiFi.mode(WIFI_STA);\n  Serial.print(\"Receiver MAC: \");\n  Serial.println(WiFi.macAddress());\n  \n  // Initialize ESP-NOW\n  esp_now_init();\n  esp_now_register_recv_cb(OnDataRecv);\n  \n  Serial.println(\"ESP-NOW Receiver ready - waiting for data...\");\n}\n\nvoid loop() {\n  delay(100);\n}"
