    "files": {
      "sketch.ino": "MOV A, #25H      ; Load immediate hexadecimal number 25H into Accumulator A\nMOV B, #04H      ; Load immediate hexadecimal number 04H into Register B\n\nMUL AB           ; Multiply A and B (25H * 04H = 0094H)\n                 ; Lower byte (94H) is stored in A\n                 ; Higher byte (00H) is stored in B\n\nMOV R0, A        ; Optional: Move lower byte result to Register 0\nMOV R1, B        ; Optional: Move higher byte result to Register 1\n\nHERE: SJMP HERE  ; End of program loop\n"
    }
