    "code": "/* \r\n * NeoPixel 8x8 Matrix - Real Rainbow Pattern \r\n * \r\n * Displays a full, vibrant, scrolling rainbow gradient \r\n * across the 8x8 WS2812B NeoPixel matrix.\r\n * \r\n * Wiring:\r\n * Matrix 5V  → Arduino 5V\r\n * Matrix GND → Arduino GND\r\n * Matrix DIN → Arduino D6\r\n */\r\n\r\n#include <Adafruit_NeoPixel.h>\r\n\r\n#define MATRIX_PIN   6\r\n#define MATRIX_SIZE 64\r\n\r\nAdafruit_NeoPixel matrix = Adafruit_NeoPixel(MATRIX_SIZE, MATRIX_PIN, NEO_GRB + NEO_KHZ800);\r\n\r\nvoid setup() {\r\n  Serial.begin(115200);\r\n  Serial.println(\"8x8 NeoPixel Matrix - Real Rainbow\");\r\n  matrix.begin();\r\n  matrix.setBrightness(60); // Moderate brightness to save power and protect eyes\r\n  matrix.show();\r\n}\r\n\r\nvoid loop() {\r\n  static uint16_t hueOffset = 0;\r\n\r\n  for (int i = 0; i < MATRIX_SIZE; i++) {\r\n    int row = i / 8;\r\n    int col = i % 8;\r\n\r\n    // 4000 maps the full 65536 HSV spectrum across the diagonal steps\r\n    uint16_t hue = hueOffset + ((row + col) * 4000);\r\n    \r\n    matrix.setPixelColor(i, matrix.ColorHSV(hue, 255, 255));\r\n  }\r\n\r\n  matrix.show();\r\n  \r\n  // Controls the speed of the rainbow movement\r\n  hueOffset += 500; \r\n  delay(30); \r\n}\r\n"
