    "code": "/*\n * Servo Sweep — Sweep servo 0 to 180 degrees\n */\n\n#include <Servo.h>\n\nServo myServo;\nint angle = 0;\nint step = 2;\n\nvoid setup() {\n  myServo.attach(9);\n  Serial.begin(115200);\n  Serial.println(\"Servo sweep started\");\n}\n\nvoid loop() {\n  myServo.write(angle);\n  Serial.print(\"Angle: \");\n  Serial.println(angle);\n\n  angle += step;\n  if (angle >= 180 || angle <= 0) {\n    step = -step;\n    delay(200);\n  }\n  delay(15);\n}"
