    "code": "/*\n * Zigbee Coordinator — Board 1\n * Sends a counter to End Device every 2 seconds\n * Green LED on D2 blinks on each send\n */\n\n#include <Zigbee.h>\n\n// End Device short address (assigned automatically)\nuint16_t endDeviceAddr = 0x0001;\n\n// Data structure to send\ntypedef struct {\n  int counter;\n  float temperature;\n} DataPacket;\n\nDataPacket myData;\nint sendCount = 0;\n\n// Callback when data is sent\nvoid onSendStatus(int status) {\n  if (status == ZIGBEE_SEND_SUCCESS) {\n    Serial.println(\"[Coordinator] Send OK\");\n  } else {\n    Serial.println(\"[Coordinator] Send FAILED\");\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(2, OUTPUT);\n\n  // Initialize Zigbee on channel 11, PAN ID 0x1234\n  Zigbee.begin(11, 0x1234);\n  Zigbee.onSend(onSendStatus);\n\n  Serial.println(\"[Coordinator] Zigbee network started!\");\n  Serial.print(\"[Coordinator] Short Address: 0x\");\n  Serial.println(Zigbee.getNodeAddress(), HEX);\n  Serial.print(\"[Coordinator] PAN ID: 0x\");\n  Serial.println(Zigbee.getPanId(), HEX);\n  Serial.print(\"[Coordinator] Channel: \");\n  Serial.println(Zigbee.getChannel());\n  Serial.println();\n}\n\nvoid loop() {\n  sendCount++;\n  myData.counter = sendCount;\n  myData.temperature = 22.5 + (sendCount % 10) * 0.5;\n\n  // Blink LED on send\n  digitalWrite(2, HIGH);\n\n  // Send data to End Device\n  Zigbee.send(endDeviceAddr, (uint8_t *)&myData, sizeof(myData));\n\n  Serial.print(\"[Coordinator] Sent #\");\n  Serial.print(sendCount);\n  Serial.print(\" temp=\");\n  Serial.println(myData.temperature);\n\n  digitalWrite(2, LOW);\n  delay(2000);\n}",
    "board2Code": "/*\n * Zigbee End Device — Board 2\n * Receives data from Coordinator (Board 1)\n * Blue LED on D2 blinks on each receive\n */\n\n#include <Zigbee.h>\n\n// Data structure to receive\ntypedef struct {\n  int counter;\n  float temperature;\n} DataPacket;\n\nDataPacket incomingData;\n\n// Callback when data is received\nvoid onDataReceived(uint8_t *data, int len) {\n  // Copy data into our struct\n  memcpy(&incomingData, data, sizeof(incomingData));\n\n  Serial.print(\"[End Device] Received #\");\n  Serial.print(incomingData.counter);\n  Serial.print(\" temp=\");\n  Serial.println(incomingData.temperature);\n\n  // Blink LED on receive\n  digitalWrite(2, HIGH);\n  delay(50);\n  digitalWrite(2, LOW);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(2, OUTPUT);\n\n  // Initialize Zigbee on same channel and PAN\n  Zigbee.begin(11, 0x1234);\n  Zigbee.onReceive(onDataReceived);\n\n  Serial.println(\"[End Device] Zigbee node ready!\");\n  Serial.print(\"[End Device] Short Address: 0x\");\n  Serial.println(Zigbee.getNodeAddress(), HEX);\n  Serial.print(\"[End Device] Waiting for data from Coordinator...\\n\");\n}\n\nvoid loop() {\n  delay(100);\n}"
